def solve(target=None):
    q=deque([start]); prev={start:None}; how={}; end=None
    while q:
        s=q.popleft()
        if len(s)==1 and (target is None or target in s): end=s; break
        for p in s:
            for dest,mid in moves[p]:
                if mid not in s: continue
                ns=set(s); ns.remove(p); ns.remove(mid); ns.add(dest); ns=frozenset(ns)
                if ns not in prev:
                    prev[ns]=s; how[ns]=(p,dest,mid); q.append(ns)
    if end is None:return None
    path=[]
    while end!=start:
        path.append(how[end]); end=prev[end]
    return path[::-1]
